select e->>'horse_no' as horse_no,e->'score_before' as score_before,e->'score_after' as score_after,e->'applied_delta' as applied_delta from public.official_predictions p cross join lateral jsonb_array_elements(p.payload->'audit'->'evidence_rank_bridge'->'per_runner') e where p.race_date='2026-11-14' and p.track='京都' and p.race_no=8 and p.status='FROZEN' order by (e->>'horse_no')::int;
